CREATE TABLE "Users" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "DiscordId" text NOT NULL,
    "AvatarUrl" text NULL,
    "Role" integer NOT NULL,
    "IsBlacklisted" boolean NOT NULL,
    "BlacklistReason" text NULL,
    "RequestCount" bigint NOT NULL DEFAULT 0,
    "ApiKeyRequestCount" bigint NOT NULL DEFAULT 0,
    "JwtRequestCount" bigint NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX "IX_Users_DiscordId" ON "Users" ("DiscordId");

CREATE TABLE "Images" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PerceptualHash" bit(64) NOT NULL,
    "Extension" text NOT NULL,
    "DominantColor" text NOT NULL,
    "Source" text NULL,
    "UploaderId" bigint NULL REFERENCES "Users" ("Id") ON DELETE SET NULL,
    "UploadedAt" timestamp with time zone NOT NULL,
    "IsNsfw" boolean NOT NULL,
    "IsAnimated" boolean NOT NULL,
    "Width" integer NOT NULL,
    "Height" integer NOT NULL,
    "ByteSize" bigint NOT NULL,
    "ReviewStatus" integer NOT NULL
);
CREATE INDEX "IX_Images_UploaderId" ON "Images" ("UploaderId");

CREATE TABLE "Tags" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Slug" text NOT NULL,
    "Description" text NOT NULL,
    "ReviewStatus" integer NOT NULL,
    "CreatorId" bigint NULL REFERENCES "Users" ("Id") ON DELETE SET NULL
);
CREATE UNIQUE INDEX "IX_Tags_Slug" ON "Tags" ("Slug");

CREATE TABLE "Artists" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Patreon" text NULL,
    "Pixiv" text NULL,
    "Twitter" text NULL,
    "DeviantArt" text NULL,
    "ReviewStatus" integer NOT NULL,
    "CreatorId" bigint NULL REFERENCES "Users" ("Id") ON DELETE SET NULL
);
CREATE UNIQUE INDEX "IX_Artists_Name" ON "Artists" ("Name");

CREATE TABLE "ImageTag" (
    "ImagesId" bigint NOT NULL REFERENCES "Images" ("Id") ON DELETE CASCADE,
    "TagsId" bigint NOT NULL REFERENCES "Tags" ("Id") ON DELETE CASCADE,
    PRIMARY KEY ("ImagesId", "TagsId")
);
CREATE INDEX "IX_ImageTag_TagsId" ON "ImageTag" ("TagsId");

CREATE TABLE "ArtistImage" (
    "ArtistsId" bigint NOT NULL REFERENCES "Artists" ("Id") ON DELETE CASCADE,
    "ImagesId" bigint NOT NULL REFERENCES "Images" ("Id") ON DELETE CASCADE,
    PRIMARY KEY ("ArtistsId", "ImagesId")
);
CREATE INDEX "IX_ArtistImage_ImagesId" ON "ArtistImage" ("ImagesId");

CREATE TABLE "Albums" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "IsDefault" boolean NOT NULL,
    "UserId" bigint NOT NULL REFERENCES "Users" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_Albums_UserId" ON "Albums" ("UserId");

CREATE TABLE "AlbumItems" (
    "AlbumId" bigint NOT NULL REFERENCES "Albums" ("Id") ON DELETE CASCADE,
    "ImageId" bigint NOT NULL REFERENCES "Images" ("Id") ON DELETE CASCADE,
    "AddedAt" timestamp with time zone NOT NULL,
    PRIMARY KEY ("AlbumId", "ImageId")
);
CREATE INDEX "IX_AlbumItems_ImageId" ON "AlbumItems" ("ImageId");

CREATE TABLE "ApiKeys" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "KeyHash" text NOT NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastUsedAt" timestamp with time zone NULL,
    "ExpirationDate" timestamp with time zone NULL,
    "UserId" bigint NOT NULL REFERENCES "Users" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX "IX_ApiKeys_KeyHash" ON "ApiKeys" ("KeyHash");

CREATE TABLE "ReviewTasks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Kind" integer NOT NULL,
    "TargetType" integer NOT NULL,
    "TargetId" bigint NOT NULL,
    "SubmitterId" bigint NULL REFERENCES "Users" ("Id") ON DELETE SET NULL,
    "Payload" jsonb NULL,
    "Reason" text NULL,
    "Status" integer NOT NULL,
    "ReviewerId" bigint NULL REFERENCES "Users" ("Id") ON DELETE SET NULL,
    "ReviewerNote" text NULL,
    "ModeratorEditedAt" timestamp with time zone NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "ResolvedAt" timestamp with time zone NULL
);
CREATE UNIQUE INDEX "IX_ReviewTasks_PendingEdit" ON "ReviewTasks" ("SubmitterId", "TargetType", "TargetId")
    WHERE "Status" = 0 AND "Kind" = 1;

CREATE TABLE "Reports" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" bigint NOT NULL REFERENCES "Users" ("Id") ON DELETE CASCADE,
    "ImageId" bigint NULL REFERENCES "Images" ("Id") ON DELETE SET NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "Status" integer NOT NULL,
    "ReviewerNote" text NULL
);

CREATE TABLE "DailyStats" (
    "Date" date PRIMARY KEY,
    "RequestCount" bigint NOT NULL
);

CREATE TABLE "GlobalStats" (
    "Key" text PRIMARY KEY,
    "Value" bigint NOT NULL
);

CREATE TABLE "SiteBanners" (
    "Id" integer PRIMARY KEY,
    "Message" text NOT NULL,
    "Variant" integer NOT NULL,
    "IsEnabled" boolean NOT NULL,
    "UpdatedAt" timestamp with time zone NULL,
    "UpdatedById" bigint NULL REFERENCES "Users" ("Id") ON DELETE SET NULL
);
